import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788002704000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="check-topic-access-says-no-but-publishing-works-anyway" tabindex="-1">check_topic_access says no, but publishing works anyway <a class="header-anchor" href="#check-topic-access-says-no-but-publishing-works-anyway" aria-label="Permalink to “check_topic_access says no, but publishing works anyway”">​</a></h2><p>Both answers are correct. <strong>ntfy grants read and write separately per topic</strong>, and the endpoint behind <code>check_topic_access</code> (<code>/{topic}/auth</code>) tests the <strong>read</strong> side only. A write-only publishing token is refused there and can still publish perfectly well — that is a correct configuration rather than a fault, and it is the single most common source of confusion with ntfy.</p><p>The tool says as much in its own result: a 401 or 403 comes back with a note that publishing may still work. If you want a token that passes the check, grant it <code>read-write</code> on the topic — but a publisher does not need read access, and not giving it any is the better shape.</p><h2 id="how-do-i-list-the-topics-on-the-server" tabindex="-1">How do I list the topics on the server? <a class="header-anchor" href="#how-do-i-list-the-topics-on-the-server" aria-label="Permalink to “How do I list the topics on the server?”">​</a></h2><p>You cannot, and neither can anything else. <strong>ntfy has no topic enumeration API.</strong> A topic exists because someone published to it, and on an instance with the default access rules its name is the whole of the access control — so a list endpoint would be a list of credentials.</p><p>The practical consequences:</p><ul><li>You either know the name or you find it in <code>get_account</code> (the topics the account is subscribed to) or <code>list_users</code> (every account and its per-topic grants, admin only).</li><li>An empty <code>list_messages</code> result usually means &quot;nothing recent on this topic&quot;, not &quot;no such topic&quot;. Retention is whatever the instance configures — 12 hours by default.</li><li>Treat topic names as secrets. <code>NTFY_TOPICS</code> keeps them out of the tool arguments entirely, because its first entry is the default for any tool called without one.</li></ul><h2 id="every-call-fails-with-setup-instructions" tabindex="-1">Every call fails with setup instructions <a class="header-anchor" href="#every-call-fails-with-setup-instructions" aria-label="Permalink to “Every call fails with setup instructions”">​</a></h2><p><code>NTFY_URL</code> is unset. The server starts and lists its tools without it on purpose, so registries and inspectors can introspect it; every call then returns the missing configuration instead of reaching the API. There is no default URL — see <a href="/guide/configuration#the-instance-url">the instance URL</a>.</p><h2 id="the-server-refuses-to-start" tabindex="-1">The server refuses to start <a class="header-anchor" href="#the-server-refuses-to-start" aria-label="Permalink to “The server refuses to start”">​</a></h2><p>Four things are fatal at startup, and each names itself on stderr:</p><ul><li><code>NTFY_TOKEN</code> set together with <code>NTFY_USERNAME</code>/<code>NTFY_PASSWORD</code>, or only one half of that pair. Which credential is in force must never be ambiguous, so this is not resolved by a precedence rule.</li><li><code>NTFY_URL</code> that does not parse, uses a scheme other than <code>http</code>/<code>https</code>, or carries credentials in the URL. The value is not echoed back — a mis-pasted token is exactly the kind of thing that lands in <code>NTFY_URL</code>, and that line is a log line.</li><li>An <code>NTFY_TOPICS</code> entry that is not a valid topic. Reported by position rather than by value, for the same reason.</li><li>An <code>NTFY_ALLOW_TOOLS</code>/<code>NTFY_DENY_TOOLS</code> entry that matches no tool, or a filter combination that would leave the tool list empty.</li></ul><h2 id="publishing-failed-with-attachments-not-allowed" tabindex="-1">Publishing failed with &quot;attachments not allowed&quot; <a class="header-anchor" href="#publishing-failed-with-attachments-not-allowed" aria-label="Permalink to “Publishing failed with &quot;attachments not allowed&quot;”">​</a></h2><p>The message body was over 4096 bytes. ntfy treats an oversized body as an attachment upload, so its error (<code>40014</code>) is about attachments and says nothing about size. <code>publish_message</code> enforces the limit itself and reports the actual byte count, but a message that reaches ntfy from somewhere else will come back with the confusing form.</p><p>The limit is in bytes, not characters: accented letters, CJK and emoji each count for more than one.</p><h2 id="i-published-to-three-topics-and-only-some-arrived" tabindex="-1">I published to three topics and only some arrived <a class="header-anchor" href="#i-published-to-three-topics-and-only-some-arrived" aria-label="Permalink to “I published to three topics and only some arrived”">​</a></h2><p>Check the <code>ok</code> field of each entry in the result rather than assuming the call succeeded as a whole. <strong>ntfy has no multi-topic publish</strong>, so <code>publish_message</code> sends one request per topic and reports each outcome separately — a rejection on one topic does not discard the ones that succeeded. Polling is the other way round: <code>list_messages</code> takes several topics in one request.</p><h2 id="i-cannot-update-a-notification-i-published" tabindex="-1">I cannot update a notification I published <a class="header-anchor" href="#i-cannot-update-a-notification-i-published" aria-label="Permalink to “I cannot update a notification I published”">​</a></h2><p><code>update_message</code> needs the <code>sequence_id</code> that <code>publish_message</code> returned, and the sequence id only exists for <strong>cached</strong> messages. One published with <code>cache: false</code> reaches the clients connected at that moment and nothing else, so it cannot be updated or deleted afterwards.</p><p><code>cache</code> and <code>firebase</code> are booleans in this server and strings in ntfy&#39;s JSON body, which wants the literal <code>&quot;no&quot;</code> and silently ignores <code>false</code>. The mapping happens here, so <code>false</code> is the right thing to pass.</p><h2 id="get-server-info-reports-version-as-unavailable" tabindex="-1">get_server_info reports &quot;version&quot; as unavailable <a class="header-anchor" href="#get-server-info-reports-version-as-unavailable" aria-label="Permalink to “get_server_info reports &quot;version&quot; as unavailable”">​</a></h2><p>That section needs an admin account, so its absence is normal for a non-admin token rather than an error. Each section is fetched independently and one that fails does not fail the call. The same object reports <code>admin_tools_available</code>, which answers &quot;should I even try <code>list_users</code>, <code>create_user</code> and the access tools?&quot; from one cheap call instead of after a confusing 401.</p><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>NTFY_READ_ONLY</code> is set, and it is a write tool.</li><li><code>NTFY_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out. <code>NTFY_ALLOW_TOOLS=essential</code> is six tools, not thirteen.</li><li><code>NTFY_DENY_TOOLS</code> names it, possibly through a prefix such as <code>delete_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot; — the same as a write tool under read-only. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};